import { readFileSync } from "fs";

const lines = readFileSync(0, "utf8").trim().split("\n");
const [, q] = lines[0].split(" ").map(Number);
const a = lines[1].split(" ").map(Number).sort((x, y) => x - y);

// a の中で x より大きい最初の位置（= x 以下の個数）を二分探索で求める
function upperBound(x: number): number {
  let lo = 0;
  let hi = a.length;
  while (lo < hi) {
    const mid = (lo + hi) >> 1;
    if (a[mid] <= x) lo = mid + 1;
    else hi = mid;
  }
  return lo;
}

const out: number[] = [];
for (let i = 0; i < q; i++) out.push(upperBound(Number(lines[2 + i])));
console.log(out.join("\n"));
